  ('zcrm_5797994000003198097', 'Cuee', 'Cuee', 'Eyiram Dodoo', 'Ahmed Raza', 'Cute provides an AI powered recruiting system for companies. It automatically analyzes resumes and identifies qualified candidates. The system conducts automated screening with structured questions to validate skills and experience. It also performs AI-led interviews, including technical assessments and performance analysis. Candidates are ranked based on scores, and top performers are fast-tracked for review. the platform provides insights and reports to guide hiring decisions. It helps reduce manual work and saves time for recruiters while maintaining a consistent evaluation process', 'HV Genesis', 'Human Development', 'Spring 2025', 'Crunchbase', 'Reached Out', 'Eyiram', 'Too Early', 'Human Development', 'Too Early', NULL, '2025-09-02 08:24:32', '2025-10-12 09:33:56', '2025-10-12 09:33:56'),
  ('zcrm_5797994000003198140', 'YieldCLub', 'YieldClub', 'Jacob Dooley', 'Mahesh Vellanki', 'YieldClub helps you grow your savings with higher returns than a traditional bank without needing to know anything about crypto or investing. We do all the heavy lifting behind the scenes so your money can work harder, while you stay in control.', 'HV Genesis', 'Financial Innovation', 'Spring 2025', NULL, 'Reached Out', 'Jacob Dooley', 'Rejected', 'Financial Innovation', NULL, NULL, '2025-09-02 13:35:55', '2026-01-05 14:52:58', '2026-01-05 14:52:58'),
