  ('zcrm_5797994000003198292', 'Stata DX', 'Stata DX', 'Kishan Angadi', 'Sidhant Jena', 'Developer of a disease management e-rapid technology designed to implement custom biomarker panels for at-home patient monitoring in clinical studies. The company''s technology is a low-cost, affinity-based electrochemical sensing platform that can simultaneously detect a broad range of biomarkers with high sensitivity and selectivity in complex biological fluids, specifically liquid MRI for the brain, enabling researchers to get information about the composition of a system in real-time.', 'HV STEM', 'Healthcare', 'Spring 2025', NULL, 'Reached Out', 'Kishan Angadi', 'Rejected', NULL, 'Founder Communication (no response etc.)', NULL, '2025-09-07 13:18:03', '2026-01-28 11:51:17', '2026-01-28 11:51:17'),
  ('zcrm_5797994000003199017', 'Future', 'Future', 'Devon Devanney', 'Blake Bianchi', 'Think Stripe for mortgages: Future connects Wall Street to brokers, replaces legacy tech, and enables full white-label loan origination.', 'HV Genesis', 'Financial Innovation', 'Spring 2025', 'Crunchbase', 'Reached Out', 'Devon Devanney', 'Rejected', 'Financial Innovation', NULL, NULL, '2025-08-31 17:40:54', '2026-01-05 14:52:58', '2026-01-05 14:52:58'),
