  ('zcrm_5797994000003201032', 'Blue Water Autonomy', 'Blue Water Autonomy', 'Vitoria Lunardi De Castro', 'Austin Gray', 'Manufacturer of autonomous ships intended to enhance national defense and improve maritime operations. The company offers modular design systems, autonomous navigation capability, and remote operational control, enabling naval forces and defense partners to increase efficiency and adaptability.', 'HV STEM', 'Manufacturing Technology', 'Spring 2025', NULL, 'Reached Out', 'Vitória Lunardi de Castro', 'Source', NULL, 'Founder Communication (no response etc.)', NULL, '2025-09-05 15:57:05', '2025-09-09 10:28:07', '2025-09-09 10:28:07'),
  ('zcrm_5797994000003201061', 'Magnefy', 'magnefy', 'Vitoria Lunardi De Castro', 'Joseph Kao Ph.D', 'Magnefy, founded in 2024 and located in California, develops an artificial intelligence-powered magnetic sensing platform aimed at real-time predictive maintenance of critical power infrastructure.', 'HV STEM', 'Manufacturing Technology', 'Spring 2025', NULL, 'Reached Out', 'Vitoria Lunardi De Castro', 'Source', NULL, 'Founder Not Interested', NULL, '2025-09-06 09:18:44', '2025-09-10 06:27:16', '2025-09-10 06:27:16'),
  ('zcrm_5797994000003201087', 'FixturFab', 'FixturFab', 'Vitoria Lunardi De Castro', 'Joe Selvik', 'Developer of a hardware testing platform designed to accelerate electronics validation from prototype to production. The company offers AI-driven test planning and integrated test equipment, enabling design and manufacturing teams to reduce development cycles and improve product quality.', 'HV STEM', 'Manufacturing Technology', 'Spring 2025', NULL, 'Reached Out', 'Vitoria Lunardi de Castro', 'Source', NULL, NULL, NULL, '2025-09-06 09:35:35', '2025-09-08 18:41:00', '2025-09-08 18:41:00'),
  ('zcrm_5797994000003201113', 'Keychain', 'Keychain', 'Vitoria Lunardi De Castro', 'Jordan Weitz', 'Developer of an AI-based consumer packaged goods manufacturing platform designed to help brands find manufacturing partners. The company''s proprietary, AI-powered platform helps brands quickly find the right manufacturing partners and provides its partners to navigate the entire manufacturing process, all the way from competitive intelligence and manufacturer sourcing, to terms negotiation, onboarding, and compliance, enabling businesses to control their entire manufacturing supply chain at ease.', 'HV STEM', 'Manufacturing Technology', 'Spring 2025', 'pitchbook', 'Reached Out', 'Vitoria Lunardi de Castro', 'Source', NULL, NULL, NULL, '2025-09-06 09:42:41', '2025-09-08 18:35:53', '2025-09-08 18:35:53'),
  ('zcrm_5797994000003201139', 'Zeteo Tech', 'Zeteo Tech', 'Vitoria Lunardi De Castro', 'Wayne Bryden', 'Zeteo Tech, founded in 2013 and located in Sykesville, MD, operates as a biodefense and medical device company focused on developing fieldable biological mass spectrometers. The company has 21 employees and its instruments are designed to identify airborne microbes, proteins, and lipids for screening infectious diseases and bio-threats.', 'HV STEM', 'Manufacturing Technology', 'Spring 2025', NULL, 'Reached Out', 'Vitória Lunardi de Castro', 'Source', NULL, NULL, NULL, '2025-09-06 09:47:14', '2025-09-09 10:27:26', '2025-09-09 10:27:26'),
  ('zcrm_5797994000003201170', 'Surface Design Solutions', 'Surface Design Solutions', 'Vitoria Lunardi De Castro', 'Tevis Jacobs', 'Operator of concrete flooring systems intended for industrial, commercial, and residential applications. The company specializes in environmentally friendly processes and offers the infinity polish system, a cost-effective which mimics the look of marble, granite, or terrazzo, enabling users with cost savings in manufacturing that increase over time.', 'HV STEM', 'Manufacturing Technology', 'Spring 2025', NULL, 'Reached Out', 'Vitoria Lunardi de Castro', 'Rejected', NULL, 'Founder Communication (no response etc.)', NULL, '2025-09-06 09:56:36', '2025-10-07 19:32:14', '2025-10-07 19:32:14'),
  ('zcrm_5797994000003201197', 'loopr', 'loopr', 'Vitoria Lunardi De Castro', 'Priyansha Bagaria', 'Developer of a visual inspection platform designed to automate quality checks and reduce manual errors in manufacturing workflows. The company''s platform features real-time defect detection, assembly verification, traceable inspection records, and compatibility across multiple industries, enabling manufacturers and production teams to streamline inspection processes, preserve operational knowledge, reduce rework, and maintain consistent quality standards at scale.', 'HV STEM', 'Manufacturing Technology', 'Spring 2025', NULL, 'Reached Out', 'Vitoria Lunardi de Castro', 'Source', NULL, NULL, NULL, '2025-09-06 10:02:03', '2025-09-08 18:24:10', '2025-09-08 18:24:10'),
  ('zcrm_5797994000003201228', 'Diode Computers', 'Diode Computers', 'Vitoria Lunardi De Castro', 'Davide Asnaghi', 'Developer of an AI-based manufacturing software designed to automate hardware designing. The company''s platform leverages generative AI models to create custom printed circuit boards and detect mistakes before manufacturing, enabling companies to design and manufacture electronics faster and cheaper.', 'HV STEM', 'Manufacturing Technology', 'Spring 2025', NULL, 'Reached Out', 'Vitoria Lunardi de Castro', 'Source', NULL, NULL, NULL, '2025-09-06 10:09:09', '2025-09-09 11:13:49', '2025-09-09 11:13:49'),
  ('zcrm_5797994000003201254', 'Industrial Next', 'Industrial Next', 'Vitoria Lunardi De Castro', 'Allen Pan', 'Industrial Next, founded in 2021 and based in San Francisco, develops AI-powered industrial automation systems aimed at reshoring and modernizing electronics manufacturing processes.', 'HV STEM', 'Manufacturing Technology', 'Spring 2025', NULL, 'Reached Out', 'Vitoria Lunardi de Castro', 'Source', NULL, NULL, NULL, '2025-09-06 10:13:46', '2025-09-09 10:27:26', '2025-09-09 10:27:26'),
  ('zcrm_5797994000003201280', 'Molg', 'molg', 'Vitoria Lunardi De Castro', 'Mark Lyons', 'Molg, founded in 2020 and headquartered in Chantilly, VA, develops circular manufacturing robots that enable autonomous assembly and disassembly of sustainable products. The company employs 47 people and focuses on advancing autonomous micro-factories using artificial intelligence and robotics to support the circular economy.', 'HV STEM', 'Manufacturing Technology', NULL, NULL, 'Reached Out', 'Vitória Lunardi de Castro', 'Source', 'Manufacturing', NULL, NULL, '2025-09-06 10:17:25', '2025-09-08 18:12:25', '2025-09-08 18:12:25'),
  ('zcrm_5797994000003201316', 'Nanopath', 'Nanopath', 'Kishan Angadi', 'Amogha Tadimety', 'Developer of a molecular diagnostic platform designed to enable point-of-care disease diagnosis. The company''s technology eliminates the need for nucleic acid amplification and supports multiplexed detection, enabling patients and providers to access actionable diagnostic results within standard office visits for improved healthcare outcomes.', 'HV STEM', 'Healthcare', 'Spring 2025', NULL, 'Reached Out', 'Kishan Angadi', 'Rejected', NULL, 'Founder Communication (no response etc.)', NULL, '2025-09-07 13:04:36', '2026-01-28 11:51:29', '2026-01-28 11:51:29'),
  ('zcrm_5797994000003201347', 'Amaros', 'Amaros', 'Kishan Angadi', 'Vartan Ghazarossian', 'Developer of an artificial intelligence software platform designed to support clinical and post-market decision-making in ophthalmology. The company''s platform collects, structures, and analyzes large datasets to accelerate clinical trial enrollment, generate real-world evidence, and identify market opportunities for life sciences companies, enabling faster and more informed therapeutic development.', 'HV STEM', 'Healthcare', 'Spring 2025', NULL, 'Reached Out', 'Kishan Angadi', 'Rejected', NULL, 'Founder Fit', NULL, '2025-09-07 16:10:33', '2026-01-28 11:53:44', '2026-01-28 11:53:44'),
