  ('zcrm_5797994000003230393', 'OneRoof', 'OneRoof', 'Khalil Thomas', 'Selin Somez', 'OneRoof connects people living in the same building to form a resourceful, fun, and supportive neighbor community. The company was founded in 2020 and is headquartered in Brooklyn, New York.', 'HV Genesis', 'Human Development', 'Spring 2025', 'Crunchbase', 'Reached Out', 'Khalil Thomas', 'Rejected', 'Human Development', NULL, NULL, '2025-09-10 07:25:29', '2026-01-05 14:52:58', '2026-01-05 14:52:58'),
  ('zcrm_5797994000003230436', 'Novaflow', 'Novaflow', 'Albert Mundadan', 'Aman Agarwal', 'Developer of an AI-powered data analysis platform designed to automate data analysis for life science researchers. The company''s platform helps scientists, labs, and biotech teams automate their bioinformatics workflows using LLMs, so they can spend less time wrangling data and more time making discoveries, provides interactive plots, clean tables, and fully traceable results, enabling researchers to get publication-ready plots in minutes instead of weeks.', 'HV STEM', 'SaaS', 'Spring 2025', NULL, 'Reached Out', 'Albert Mundadan', 'Source', NULL, NULL, NULL, '2025-09-10 07:40:26', '2025-09-10 07:40:26', NULL),
  ('zcrm_5797994000003230492', 'Synthefy', 'Synthefy', 'Albert Mundadan', 'Shawn Jain', 'Developer of a multi-modal time series analysis platform designed to provide actionable insights from time series data. The company''s platform incorporates state-of-the-art generative artificial intelligence technology to analyze multivariate time series, contextual metadata, and digital twin simulations, enabling businesses to perform stress testing, anomaly detection, forecasting, and capacity planning, ultimately boosting the accuracy of their data-driven decisions and predictions.', 'HV STEM', 'SaaS', 'Spring 2025', 'Pitchbook', 'Reached Out', 'Albert Mundadan', 'Source', NULL, NULL, NULL, '2025-09-10 07:49:27', '2025-09-10 07:49:27', NULL),
  ('zcrm_5797994000003230532', 'Testaify', 'Testaify', 'Albert Mundadan', 'Rafael Santos', 'Developer of an artificial intelligence-based autonomous testing platform designed to help software development organizations find and fix defects faster and with less effort. The company''s platform offers tools to model applications, generate and execute tests, create input data, write tests using different testing methodologies, and validate defects found, enabling businesses to focus on the strategic aspects of their job.', 'HV STEM', 'SaaS', 'Spring 2025', 'Pitchbook', 'Reached Out', 'Albert Mundadan', 'Source', NULL, NULL, NULL, '2025-09-10 07:55:21', '2025-09-10 07:55:21', NULL),
