  ('zcrm_5797994000003248337', 'UXcam', 'UXCam', 'Shakshi Patel', 'Silvanus', 'Developer of a user interface experience optimization tool designed to set up and maintain pipelines to gather comprehensive usage data from applications. The company''s tool works in the background without any performance penalty and helps to record and analyze user experiences while understanding the problems and bugs in their applications, enabling businesses to understand how users use the product and understand where they get frustrated.', 'HV STEM', 'SaaS', 'Fall 2025', NULL, 'Reached Out', 'Shakshi Patel', 'Source', NULL, 'Founder Communication (no response etc.)', NULL, '2025-09-23 15:31:08', '2025-10-05 16:28:36', '2025-10-05 16:28:36'),
  ('zcrm_5797994000003248363', 'Coperniq', 'Coperniq', 'Shakshi Patel', 'Max', 'Developer of a workflow management software designed to help solar installers manage their projects effectively. The company''s platform offers cloud-driven data collection and agile management tools for building external and internal team collaboration, project management, human error prevention, and data storage, enabling clients to make informed data-driven decisions and boost their project profitability.', 'HV STEM', 'SaaS', 'Fall 2025', NULL, 'Reached Out', 'Shakshi Patel', 'Source', NULL, NULL, NULL, '2025-09-23 15:35:37', '2025-09-23 15:35:37', NULL),
